    if (isBlank(row.release_date)) { const d = missingDate(fields.supplier_code); if (d) { row.release_date = d; row.extra.release_date_tbc = true; } }
    row.missing_fields = MANDATORY.filter(function (f) { return isBlank(row[f]); });
    rowSource.push(msgId);   // recorded as produced above, before matching
    if (!stubTemplateBySource[msgId]) stubTemplateBySource[msgId] = { label: row.label, supplier_code: row.supplier_code, catalog: row.catalog, thread_id: row.thread_id, source_email: row.source_email, calculation_group: row.calculation_group };
    rows.push({ json: Object.assign({ action: 'create', match_line_id: null }, row) });
  }
}
// ---- v42 COMPLETENESS GATE -------------------------------------------------------
// Measure what came out against what the source printed. A barcode that produced no line
// and was not deliberately dropped is a release the client will never see, so it is named
// on every line of that message — where they work, not only in the raw-entry audit.
// v58: every EAN that already has a catalog line. The gate below runs BEFORE the stub pass
// and has to know which dropped barcodes will actually get a stub, so this moved up from there.
const poolEans = {};
for (const _l of allLines) { const _k = keyEan(_l.ean); if (_k) poolEans[_k] = true; }
// The full completeness text per source, for the STUB rows that pass it on to a reviewer.
const gateFullBySource = {};

// ---- v63 A RELEASE READ TWICE IS ONE RELEASE -------------------------------------
// The 11.09 PIAS mail carried the album artwork as separate JPGs and a one-sheet with no barcode on
// it. The model read them as releases — correctly, there IS a release on that page — so ANATOMY OF
// A BRIEF ROMANCE (LP) came out as THREE rows: one with its barcode and two without. In-run dedupe
// keys on EAN, then on catalogue number; an item that has neither has no key at all, and `code` is
// null so the database's unique index cannot catch it either (client, 2026-09-11).
//
// A barcode-less release is still a release and is never dropped for lacking one — that is v47, and
// it stands. What is dropped here is narrower: a NEW row with no barcode AND no catalogue number
// whose artist, title and format are already carried, in this same run and from this same document,
// by a row that DOES have a barcode. That is not a second release, it is the same one read off a
// second page, and the barcoded row is the better copy of it. Run after every row is built, because
// the pages arrive in any order — on that run the barcode-less copy came three parts BEFORE the
// barcoded one — and named in the receipt below, never dropped silently.
const mergedTwiceBySource = {};
(function () {
  const sidOf = function (j) { return String((j.extra && j.extra.source_message_id) || j.thread_id || ''); };
  const idy = function (j) {
    const a = String(j.artist == null ? '' : j.artist).trim().toUpperCase();
    const t = String(j.title == null ? '' : j.title).trim().toUpperCase();
    const f = String(j.format == null ? '' : j.format).trim().toUpperCase();
    return (a && t) ? a + '\u0001' + t + '\u0001' + f : null;
  };
  const identified = {};
  for (const r of rows) {
    const j = r.json;
    if (!j || isBlankish(j.ean)) continue;
    const k = idy(j);
    if (!k) continue;
    const sid = sidOf(j);
    identified[sid + '\u0002' + k] = (printedBySource[sid] || {})[keyEan(j.ean)] || String(j.ean);
  }
  for (let i = rows.length - 1; i >= 0; i--) {
    const j = rows[i].json;
    if (!j || j.action !== 'create') continue;
    if (!isBlankish(j.ean) || !isBlankish(j.catalogue_no)) continue;
    const k = idy(j);
    if (!k) continue;
    const sid = sidOf(j);
    const twin = identified[sid + '\u0002' + k];
    if (!twin) continue;
    if (!mergedTwiceBySource[sid]) mergedTwiceBySource[sid] = [];
    mergedTwiceBySource[sid].push(String(j.artist) + ' — ' + String(j.title) + ' → ' + twin);
    rows.splice(i, 1);
    rowSource.splice(i, 1);   // the gate below reads these two arrays in step
  }
})();
for (let i = 0; i < rows.length; i++) {
  const id = rowSource[i];
  // Only a NEW line carries the warning. An update is a follow-up to a line that already
  // exists, its `extra` belongs to that line, and writing to it here would overwrite what is
  // stored rather than add to it.
  if (!id) continue;
  const printed = printedBySource[id] || {};
  const produced = producedBySource[id] || {};
  const dropped = droppedBySource[id] || {};
  const missing = [];
  for (const k in printed) {
    if (!Object.prototype.hasOwnProperty.call(printed, k)) continue;
    if (produced[k] || dropped[k]) continue;
    missing.push(k);
  }
  // v47: and the releases the source shows with an EMPTY barcode field. They cannot be
  // counted in `printed` — they have nothing to count — so a run can look complete at
  // 37 of 37 barcodes while two releases are missing. Every blank field the model DID
  // report comes back as an item with no barcode; the rest are gone.
  const _blank = blankFieldsBySource[id] || 0;
  const _unreported = Math.max(0, _blank - (eanlessBySource[id] || 0));
  // v49: the count the chunker asserted against the count the model returned. Compared on
  // ITEMS, not rows, so the lines this file drops on purpose — digital releases, fee lines,
  // junk, a blocked promo — can never raise a false alarm.
  const _announced = announcedBySource[id] || 0;
  const _returned = itemsBySource[id] || 0;
  const _short = Math.max(0, _announced - _returned);
  // v59: EVERY PRINTED BARCODE IS ACCOUNTED FOR, OUT LOUD.
  // A barcode can legitimately produce no row — its line already exists and this document
  // changes nothing, the AI returned it twice, it is excluded on purpose — so the row count is
  // routinely lower than the barcode count with nothing on screen to explain the gap. That gap
  // is what the client keeps reading as data loss, and they are right to read it that way: an
  // unexplained shortfall is indistinguishable from a real one. Printed only when there IS a
  // gap, so a run whose two numbers agree stays silent.
  const _skipped = skippedBySource[id] || {};
  const _skipExists = [], _skipDupe = [];
  for (const _k in _skipped) { if (_skipped[_k] === 'duplicate') _skipDupe.push(_k); else _skipExists.push(_k); }
  const _dropCount = countKeys(dropped);
  const _twice = mergedTwiceBySource[id] || [];                                    // v63
  const _partsAll = _allChunks.filter(function (c) { return String(c.message_id) === String(id); }).length;
  const _partsGone = Math.max(0, _partsAll - (arrivedPartsBySource[id] || 0));     // v63
  // Only the buckets NOTHING ELSE names: a stub and an already-covered barcode are each
  // spelled out by the sentences above, and repeating them here would be the same fault
  // this note exists to cure. The receipt is for the gap a reader cannot otherwise close.
  const _silent = _skipExists.length + _skipDupe.length + _dropCount + _twice.length;
  // v59: AS PRINTED. Every one of these lists holds NORMALISED keys — leading zeros stripped —
  // and a reviewer has to find the digits on the page: "198029909012" is not what the invoice
  // shows, and a barcode a reviewer cannot find reads as a bug in the note or a bug in the run.
  const _asPrinted = function (k) { return printed[k] || k; };
  if (!missing.length && !_unreported && !_short && !_silent && !_partsGone) continue;
  // v58: THE NOTE MUST SAY WHAT ACTUALLY HAPPENED, ONCE.
  // Three things were wrong with it on a 48-barcode document (client, 2026-09-10).
  // It promised "added as a STUB row" for every dropped barcode, including the ones that
  // already have a catalog line and correctly get no stub — so the note described a rescue
  // that had not happened. It then printed a second paragraph about the SAME five releases,
  // headed differently, which is not a second check but the same check said twice. And it
  // put all of that on all 43 rows of the run, so the reviewer met the same block 43 times.
  // A warning that overstates itself, repeats itself and fires on every row is one the
  // reviewer learns to skim — and then skims the run where it mattered.
  const _stubbed = [], _covered = [];
  for (const _k of missing) (poolEans[_k] ? _covered : _stubbed).push(_k);
  const _full = [], _brief = [];
  if (missing.length) {
    const shown = missing.slice(0, 12).map(_asPrinted).join(', ') + (missing.length > 12 ? ', …' : '');
    let s = 'INCOMPLETE EXTRACTION: this document printed ' + countKeys(printed) + ' barcodes but produced ' +
      countKeys(produced) + ' catalog lines. ' + missing.length + ' barcode(s) came back from the AI as nothing at all: ' + shown + '.';
    if (_stubbed.length) s += ' ' + _stubbed.length + ' of them ' + (_stubbed.length === 1 ? 'has' : 'have') +
      ' been added as a STUB row (flagged for review) so the release is NOT lost — complete it from the source before approving.';
    if (_covered.length) s += ' ' + _covered.length + ' of them already ' + (_covered.length === 1 ? 'has' : 'have') +
      ' a catalog line, so nothing was lost there and no stub was added.';
    _full.push(s);
    _brief.push(_stubbed.length
      ? 'INCOMPLETE EXTRACTION: ' + missing.length + ' barcode(s) in this document produced no line from the AI. ' +
        _stubbed.length + ' of them ' + (_stubbed.length === 1 ? 'is' : 'are') + ' in this batch as a STUB row, flagged for review — complete ' +
        (_stubbed.length === 1 ? 'it' : 'them') + ' from the source before approving.'
      : 'EXTRACTION NOTE: ' + missing.length + ' barcode(s) in this document produced no line from the AI; each already has a catalog line, so nothing was lost.');
  }
  // Deliberately NOT headed "INCOMPLETE EXTRACTION". That phrase is reserved for a fact —
  // a barcode printed in the document that produced no line, named. This one is an
  // inference from two counts, and the count of releases in a document is a reading, not
  // a measurement. Keeping the two apart is what stops the hard signal being worn down by
  // the soft one; a reviewer who learns to skim past this must not learn to skim past that.
  // v58: and it earns its place only when it sees MORE than the named barcodes already show.
  if (_short > missing.length) {
    const s = 'POSSIBLE MISSING RELEASE: this document was read as holding at least ' + _announced + ' releases and the AI returned ' + _returned +
      ' — ' + _short + ' fewer' + (missing.length ? ', which is ' + (_short - missing.length) + ' more than the barcode(s) named above' : '') +
      '. This check does not depend on barcodes at all, so it is the one that can see a release the others cannot. Compare against the source before approving.';
    _full.push(s); _brief.push(s);
  }
  if (_unreported) {
    const s = 'INCOMPLETE EXTRACTION: this document shows ' + _blank + ' release(s) whose barcode field is printed but EMPTY, and ' +
      _unreported + ' of them came back from the AI as nothing at all. A release with no barcode is still a release — it is ' +
      'usually one the label has not finalised. Read the source and add it by hand if the client wants it.';
    _full.push(s); _brief.push(s);
  }
  if (_partsGone) {
    const s = 'PART NOT EXTRACTED: this document was split into ' + _partsAll + ' part(s) and ' + _partsGone +
      ' of them produced no items at all — either the AI judged the part irrelevant, or its answer could not be read as JSON and was dropped before this check. Open the run and read the "Unread AI Answer" branch to see which. Every barcode printed in the document is still accounted for above; a release in that part that prints NO barcode is not.';
    _full.push(s); _brief.push(s);
  }
  if (_silent) {
    const _rest = _silent + _stubbed.length + _covered.length;
    const _bits = [];
    if (_skipExists.length) _bits.push(_skipExists.length + ' already ' + (_skipExists.length === 1 ? 'has a catalog line' : 'have catalog lines') +
      ' that this document does not change (' + _skipExists.slice(0, 6).map(_asPrinted).join(', ') + (_skipExists.length > 6 ? ', …' : '') + ')');
    if (_skipDupe.length) _bits.push(_skipDupe.length + ' came back from the AI twice and ' + (_skipDupe.length === 1 ? 'was' : 'were') + ' merged into one line');
    if (_dropCount) _bits.push(_dropCount + ' excluded on purpose');
    if (_twice.length) _bits.push(_twice.length + ' ' + (_twice.length === 1 ? 'was' : 'were') +
      ' read a second time off a page that prints no barcode (artwork, a one-sheet) and merged into the barcoded line (' +
      _twice.slice(0, 4).join('; ') + (_twice.length > 4 ? '; …' : '') + ')');
    if (_stubbed.length) _bits.push(_stubbed.length + ' added as a STUB row');
    if (_covered.length) _bits.push(_covered.length + ' that the AI dropped but which already ' + (_covered.length === 1 ? 'has a line' : 'have lines'));
    const _acct = 'EXTRACTION NOTE: this document prints ' + countKeys(printed) + ' barcodes and this run wrote ' +
      Math.max(0, countKeys(printed) - _rest) + ' line(s) of its own. The other ' + _rest + ': ' + _bits.join('; ') +
      '. Nothing is missing — the two numbers differ for the reasons listed.';
    _full.push(_acct);
    _brief.push(_acct);
  }
  if (_full.length) gateFullBySource[id] = _full.join('\n');
  if (!_brief.length) continue;
  // Flag the ordinary rows only when something is still UNRESOLVED. When every dropped
  // barcode already has a catalog line there is nothing for a reviewer to do, and marking
  // 43 finished rows for review is exactly the noise that hides the run where it matters.
  if (_stubbed.length || _unreported || _partsGone || _short > missing.length) rows[i].json.extra.needs_review = true;
  rows[i].json.extra.review_note = appendNote(rows[i].json.extra.review_note, _brief.join('\n'));
}

// ---- v56: NEVER LOSE A PRINTED BARCODE --------------------------------------------
// The gate above NAMES every barcode the AI dropped; here each one that is not already a
// catalog line becomes a STUB so it cannot be silently lost. The EAN is copied exactly from
// the document (never invented); artist/title are read from the barcode's own pipe-table row
// when there is one, else the raw line is kept in the note. Flagged needs_review, status
// in_progress -> never sent to Hermes until a human completes it (Mare, I-DI Invoice, 2026-09-09).
function stubCells(line) {
  const raw = String(line == null ? '' : line).split('|').map(function (s) { return s.trim(); });
  if (raw.length && raw[0] === '') raw.shift();
  if (raw.length && raw[raw.length - 1] === '') raw.pop();
  return raw;
}
function stubIsName(v) { return !!v && /[A-Za-z]/.test(v) && !/^[\d.,%\/-]+$/.test(v); }
// artist + title from the barcode's own line, but ONLY when it is a pipe-table row (cell
// after the barcode, then the next). A barcode in prose keeps its whole line in the note
// and leaves the fields blank rather than guess where a name begins.
// v58: looked up in BOTH renderings — the raw document and the one Chunk Source handed the
// model — and the FULLER of the two wins. Where an unaligned table was rewritten, the raw
// rendering holds only the fragment the parser broke the record into; the rewritten one holds
// the whole line, so the reviewer completing the stub can do it from the note instead of
// reopening the PDF. Both hits are that barcode's own line, so neither can belong to another
// release.
function stubNames(text, flat, rawBarcode) {
  const out = { artist: null, title: null, line: null };
  let hit = null;
  for (const src of [String(text == null ? '' : text), String(flat == null ? '' : flat)]) {
    for (const l of src.split('\n')) {
      if (l.indexOf(rawBarcode) === -1) continue;
      if (hit === null || l.length > hit.length) hit = l;
      break;
    }
  }
  if (!hit) return out;
  out.line = hit.trim().slice(0, 300);
  if (hit.trim().charAt(0) === '|') {
    const cells = stubCells(hit);
    let bi = -1;
    for (let i = 0; i < cells.length; i++) { if (cells[i].indexOf(rawBarcode) !== -1) { bi = i; break; } }
    if (bi !== -1) {
      const after = cells.slice(bi + 1).filter(stubIsName);
