}
const stubs = [];
for (const sid in printedBySource) {
  if (!Object.prototype.hasOwnProperty.call(printedBySource, sid)) continue;
  // v62: A DOCUMENT THE AI READ NOTHING FROM MUST STILL PRODUCE ITS BARCODES.
  // The template below carries the fields that belong to the MESSAGE rather than to a release -
  // label, supplier code, catalog, thread, source - and it used to be cloned off the first real
  // row. When the AI returned no items at all there was no row to clone, so this loop skipped the
  // document entirely: every printed barcode gone, and not one note anywhere saying so. That is
  // the exact failure the stub net exists to prevent, and it sat in it from v56 until the corpus
  // harness crossed three real documents with an AI that returns nothing (2026-09-10).
  // Nothing here is invented: every field is read from the source or from the client's own
  // Senders table, and a field neither can supply stays null and is flagged as missing.
  let tmpl = stubTemplateBySource[sid];
  const _noRows = !tmpl;
  if (!tmpl) {
    const _s = srcBySource[sid] || {};
    const _tbl = senderTableLabel(_s);
    const _lbl = up(nullIfBlankish(messageLabel(sid)) || labelTemplatePrefix(_tbl) || _tbl) || null;
    tmpl = {
      label: _lbl,
      supplier_code: supplierCodeFor(_lbl, _lbl),
      catalog: invoiceSources.has(sid) ? 'other' : 'main',
      thread_id: _s.thread_id ?? null,
      source_email: sourceEmail(_s),
      calculation_group: '1',
    };
  }
  const printed = printedBySource[sid] || {};
  const produced = producedBySource[sid] || {};
  const dropped = droppedBySource[sid] || {};
  const text = sourceTextBySource[sid] || '';
  for (const k in printed) {
    if (!Object.prototype.hasOwnProperty.call(printed, k)) continue;
    if (produced[k] || dropped[k] || poolEans[k]) continue;   // already a line, or dropped on purpose
    const raw = printed[k];
    const ean = toEan13(raw);
    if (!ean) continue;                       // not a barcode length -> never manufacture one (v44)
    const nm = stubNames(text, flatTextBySource[sid] || '', raw);
    const stub = {
      action: 'create', match_line_id: null, status: 'in_progress',
      label: tmpl.label, catalog: tmpl.catalog, thread_id: tmpl.thread_id, source_email: tmpl.source_email,
      artist: nm.artist, title: nm.title, format: null, genre: null, unit: 1,
      ean: ean, code: toCatalogCode(raw), catalogue_no: null, release_date: null,
      price_original: null, currency: null, cop: null, ppd: null, rock_bottom: null, our_price: null,
      calculation_group: tmpl.calculation_group, supplier_code: tmpl.supplier_code, confidence: 0, notes: null,
      extra: { stub: true, needs_review: true, source_message_id: sid, artist_raw: nm.artist,
        review_note: (_noRows ? 'THE AI RETURNED NOTHING AT ALL FOR THIS DOCUMENT, so every barcode it prints has been added as a STUB row from the source and nothing is lost. Read the document and complete these rows by hand, and tell whoever maintains the workflow that a whole document came back empty. ' : '') + 'AUTO-ADDED: the AI dropped this barcode from a part of the source it could not read. The barcode is copied exactly from the document; verify artist / title / format / price against it before approving.' + (nm.line ? ' Source line: ' + nm.line : '') + (gateFullBySource[sid] ? '\n' + gateFullBySource[sid] : '') },
    };
    if (isBlank(stub.release_date)) { const d = missingDate(stub.supplier_code); if (d) { stub.release_date = d; stub.extra.release_date_tbc = true; } }
    stub.missing_fields = MANDATORY.filter(function (f) { return isBlank(stub[f]); });
    stubs.push({ json: stub });
  }
}
for (const _s of stubs) rows.push(_s);

return rows;

