// ---- v13 Build Raw Entry1 logic (testable copy of the n8n code node body) ----
// buildRawEntry(inputs, srcFor) where srcFor(i) returns the matching Chunk Source
// json (the n8n node uses `$("Chunk Source").itemMatching(i)` with a `.first()`
// fallback).
//
// One raw_entries row per SOURCE. The completeness audit — every barcode printed in
// the source must come back as an item — is written INSIDE `extracted` (jsonb), NOT
// as a dedicated top-level column. That is the fix for the v12 insert failure: the
// Supabase node auto-maps its input to real columns, so a top-level key with no
// column (extraction_audit) makes the whole insert fail and the audit row — the only
// trace of the email — is lost. `extracted` always exists, so the insert can never
// fail on it; the Raw Entries page surfaces extracted.extraction_audit as a column.
const BARCODE_RE = /\b\d{12,14}\b/g;

function keyEan(v) {
  const s = String(v === null || v === undefined ? '' : v).replace(/\D/g, '').replace(/^0+/, '');
  return s || null;
}

function buildRawEntry(inputs, srcFor) {
  const bySource = {};
  const order = [];
  for (let i = 0; i < inputs.length; i++) {
    let result = inputs[i].json;
    result = result.output != null ? result.output : (result.message && result.message.content != null ? result.message.content : (result.content != null ? result.content : result));
    if (typeof result === 'string') { const a = result.indexOf('{'), b = result.lastIndexOf('}'); try { result = JSON.parse(a >= 0 && b > a ? result.slice(a, b + 1) : result); } catch (e) {} }

    const src = srcFor(i) || {};
    const id = src.message_id != null ? src.message_id : 'unknown';
    if (!bySource[id]) { bySource[id] = { src: src, items: [], rows: 0, parts: 0, text: '' }; order.push(id); }
    const b = bySource[id];
    b.items = b.items.concat((result && result.items) || []);
    b.rows += Number(src.chunk_rows || 0);
    b.parts += 1;
    b.text += '\n' + (src.body || '') + '\n' + (src.attachments_text || '');
    if (result) {
      if (b.label == null && result.label != null) b.label = result.label;
      if (b.confidence == null && result.overall_confidence != null) b.confidence = result.overall_confidence;
      if (b.relevant == null && result.is_catalog_relevant != null) b.relevant = result.is_catalog_relevant;
      if (b.reason == null && result.relevance_reason != null) b.reason = result.relevance_reason;
      if (result.needs_review) b.needs_review = true;
      if (result.review_reasons) b.review_reasons = (b.review_reasons || []).concat(result.review_reasons);
    }
  }

  return order.map(function (id) {
    const b = bySource[id];
    const bodyFull = b.src.body_full != null ? b.src.body_full : (b.src.body != null ? b.src.body : null);
    const attFull = b.src.attachments_full != null ? b.src.attachments_full : null;
    const full = attFull === null && bodyFull === null ? b.text : [bodyFull || '', attFull || ''].join('\n');

    const returned = {};
    for (const it of b.items) { const k = keyEan(it && it.ean); if (k) returned[k] = true; }
    const printed = [];
    const seen = {};
    const found = full.match(BARCODE_RE) || [];
    for (const raw of found) { const k = keyEan(raw); if (k && !seen[k]) { seen[k] = true; printed.push(raw); } }
