// barcode, and (c) actually has a wrapped row. A table that reads cleanly is left alone.
const UNALIGNED_MARK = '[THE PARSER COULD NOT ALIGN THIS TABLE, SO IT HAS BEEN REWRITTEN ONE LINE PER RELEASE. Each line below that begins with a 12-14 digit barcode is ONE release, and everything after that barcode on the same line belongs to it — artist, then title, then units / format / price in an order that may vary. ONE VALUE IS OFTEN SPLIT ACROSS SEVERAL NEIGHBOURING CELLS: a title can run on through three or four of them, with a quantity or a price sitting in between, so read the whole line before deciding where the title ends and join the pieces back together rather than stopping at the first cell boundary. Do not assume the first line names the columns: if it does not, its cells belong to the release printed immediately above this table. A line that does not begin with a barcode is not a release of its own. These lines are harder to read than the rest of the document; read them anyway — every one of them is a release the client sells.]';
const UNALIGNED_RE = /^\[THE PARSER COULD NOT ALIGN THIS TABLE/;
function hasLetter(s) { return /[A-Za-z]/.test(String(s)); }
function foldRow(row) {
  const lines = String(row).split('\n');
  const cells = cellsOf(lines[0]);
  const tail = [];
  for (let i = 1; i < lines.length; i++) {
    const cs = cellsOf(lines[i]).filter(function (c) { return c !== ''; });
    if (!cs.length) continue;
    let letters = false;
    for (const c of cs) if (hasLetter(c)) letters = true;
    if (letters) { for (const c of cs) cells.push(c); }
    else tail.push('| ' + cs.join(' | ') + ' |');
