}
function flattenUnalignedTables(text) {
  let rewrote = false;
  const lines = String(text == null ? '' : text).split('\n');
  const segs = [];
  for (const l of lines) {
    const type = isTableLine(l) ? 'table' : 'text';
    if (!segs.length || segs[segs.length - 1].type !== type) segs.push({ type: type, lines: [] });
    segs[segs.length - 1].lines.push(l);
  }
  const out = [];
  for (const s of segs) {
    if (s.type !== 'table') { for (const l of s.lines) out.push(l); continue; }
    const tp = splitTableSeg(s.lines);
    let wrapped = false;
    if (tp && !tp.structured && tp.barcoded > 0) {
      for (const r of tp.rows) if (String(r).indexOf('\n') !== -1) wrapped = true;
    }
    if (!wrapped) { for (const l of s.lines) out.push(l); continue; }
    rewrote = true;
    // v59: RECLAIM THE RELEASE THE PARSER TURNED INTO A PAGE HEADER.
    // When LlamaParse cannot find a table's columns it can also fail to find where the table
    // STARTS. On I-DI page 2 it emitted the first product as loose text above the table
    // ("5056083208579  Yes  Hanns-Martin-Schleyer-Halle. Stuttgart. 3  Germany.", returned as
    // pageHeaderMarkdown) and left that release's remaining cells — CD, 31St May, 1991, 9,99 —
    // in the table's header row. One record, in two pieces, in two different kinds of block:
    // it is the ONE release the model still did not return after v58 rewrote the rest of the
    // page (client, 2026-09-10).
    // The halves are joined into the table's first row. Every condition below must hold, and
    // each is something the document SHOWS rather than something inferred:
    //   - the head names no identifier column, so it is not really a header;
    //   - no line of the head carries a barcode, so none of them is a product row of its own;
    //   - the last non-blank line before the table is NOT a table line, carries exactly one
    //     barcode, and that barcode appears nowhere inside the table itself.
    // Anything else and both halves stay exactly where the parser put them.
    let head = tp.head, reclaimed = null;
    if (!namesIdColumn(tp.head)) {
      const cont = [];
      let usable = true;
      for (const h of tp.head) {
        if (isSep(h)) continue;
        if (BARCODE_RE.test(h)) { usable = false; break; }
        const cs = cellsOf(h).filter(function (c) { return c !== ''; });
        if (cs.length) cont.push(cs);
      }
      let j = out.length - 1;
      while (j >= 0 && String(out[j]).trim() === '') j--;
      const prev = j >= 0 ? String(out[j]) : '';
      const codes = barcodeList(prev);
      const inTable = barcodeKeys(s.lines.join('\n'));
      if (usable && cont.length && j >= 0 && !isTableLine(prev) && !UNALIGNED_RE.test(prev.trim()) &&
          codes.length === 1 && !inTable[String(codes[0]).replace(/^0+/, '')]) {
        // the loose line is column-separated by runs of whitespace, the way the parser laid it out
        const cells = prev.trim().split(/\s{2,}/).map(function (c) { return c.trim(); }).filter(function (c) { return c !== ''; });
        for (const cs of cont) for (const c of cs) cells.push(c);
        reclaimed = '| ' + cells.join(' | ') + ' |';
        out.splice(j, 1);
        head = tp.head.filter(isSep);
      }
    }
    out.push(UNALIGNED_MARK);
    for (const l of head) out.push(l);
    if (reclaimed) out.push(reclaimed);
    for (const r of tp.rows) out.push(foldRow(r));
  }
  return { text: out.join('\n'), rewrote: rewrote };
}

// Split one Markdown blob (an email body or one attachment) into parts of at most
// MAX_ROWS product rows. Returns { total, confident, prose, parts }.
//   total     = counted product rows across every clean table in the blob.
//   confident = total>0 AND every "|" run we counted looked like a real, separator-
//               delimited table (so `total` can be trusted as an EXACT count).
//   prose     = words of running text outside the tables (may itself list releases).
// A blob that fits in one part is returned whole (only the count is added).
function chunkBlob(text, repeatHeader) {
  const _flat = flattenUnalignedTables(text);   // v58: one line per release before anything counts it
  text = _flat.text;
  const lines = String(text || '').split('\n');
  const segs = [];
  for (const l of lines) {
    const type = isTableLine(l) ? 'table' : 'text';
    if (!segs.length || segs[segs.length - 1].type !== type) segs.push({ type: type, lines: [] });
    segs[segs.length - 1].lines.push(l);
  }

  let total = 0;    // PRODUCT rows only — this is the number asserted to the model
  let rowTotal = 0; // every row, fee rows included — this is what the splitter budgets
  let messyTable = false; // a "|" run we could not parse, or a table with no separator
  // v59: a table we had to REWRITE starts the blob off as a floor. Its rows are countable only
  // because we repaired them, so the number is OUR reading of the page and not the document's
  // own structure — and "EXACTLY n" may only ever be said of what the document shows (v49, v55,
  // v57). Without this the I-DI invoice would now be asserted "EXACTLY 48", which is right up
  // until the day a repair is wrong, and then it is an order to drop a real release.
  let softCount = _flat.rewrote;  // v49: a counted row that prints no barcode -> the count is a floor
  let prose = 0;
  for (const s of segs) {
    if (s.type === 'table') {
      s.tp = splitTableSeg(s.lines);
      if (s.tp) {
        total += s.tp.products; rowTotal += s.tp.rows.length;
        if (!s.tp.hasSep) messyTable = true;
        // v49: a counted row with no printed barcode makes the total a FLOOR, not a total.
        if (s.tp.products !== s.tp.barcoded) softCount = true;
      }
      else { messyTable = true; prose += proseWords(s.lines); }
    } else {
      prose += proseWords(s.lines);
    }
  }
  // v42: do the tables actually SEE every release? If the blob carries more distinct
  // barcodes than the table pass accounted for, releases are being printed outside tables
  // and the row budget cannot be trusted — split by release instead. Requires two or more
  // headings, so an invoice with one big product table (where barcodes and rows agree) is
  // never routed here and its behaviour is untouched.
  const blobCodes = countKeys(barcodeKeys(text));
  // v55: a count is EXACT only when the tables saw EVERY barcode in the blob. A barcode
  // stranded in prose — I-DI's "5056083208579  Yes  Hanns-Martin-Schleyer-Halle...", printed
  // above a mangled table — is not in `total`, so a part holding 12 releases was asserted as
  // "exactly 11" and the model dropped one (5060572510005, Mare 2026-09-09). "Exactly n" is
  // an order; one short, it drops a row. So blobCodes > total downgrades the count to a floor
  // ("extract every release, never stop early"); the completeness gate remains the backstop.
  // The v42 by-heading SPLIT below still needs >=2 headings — only the confidence is general.
  // v57: each stranded barcode is a release the tables missed, so it joins the FLOOR — but
  // never `confident`. That it IS a release is an inference, and "EXACTLY n" may only be
  // said of something observed (v49). softCount carries it outward, which is exactly what
  // softCount means: this count is a floor, not a total.
  const strandedList = strandedKeys(text);
  const confident = total > 0 && !messyTable && !softCount && blobCodes <= total && strandedList.length === 0;
  if (countHeadings(text) >= 2 && blobCodes > total) {
    const whole = String(text || '');
    // v48: every release, not every barcode. The routing test above is deliberately left on
    // barcodes alone — it asks whether the TABLES saw everything, and widening it would send
    // documents down this path that are handled correctly today.
    const blobReleases = blobCodes + blankBarcodeFields(whole);
    const parts = (blobReleases > MAX_ITEMS || whole.length > MAX_PART_CHARS)
      ? splitByHeadings(whole)
      : [{ text: whole, rows: blobReleases, products: blobReleases }];
    // `confident` stays false: some releases print no barcode at all, so the count is a
    // FLOOR, never an exact total. note() asserts it as "at least N".
    return { total: blobReleases, rowTotal: blobReleases, confident: false, prose: prose, parts: parts, byHeading: true };
  }

  // v49: no table the row-counter could use, but barcodes on the page. Assert their count as
  // a floor — never as a total, since a release can print no barcode at all.
  if (total === 0 && blobCodes > 0) {
    const floor = blobCodes + blankBarcodeFields(String(text || ''));
    if (rowTotal <= MAX_ROWS) {
