        curRows = 0;
        curProducts = 0;
        if (heading) { cur.push(heading); cur.push(''); }
        if (header) { cur.push(HEADER_MARK); cur.push(header); cur.push(''); }
        // v42: name the title these rows belong to. Cutting inside a table used to leave the
        // next part opening with a bare barcode whose heading had stayed behind, and the
        // model attached it to the NEXT product it could see. Written as a marked context
        // line rather than as a heading, so it identifies the rows without inviting a second
        // item for a release already extracted in the part before.
