  // v57: assigned to the FIRST part that carries it, so a barcode sitting in a repeated
  // context header is counted once for the document and never once per part.
  for (const _k of strandedList) {
    for (const _p of parts) {
      if (barcodeKeys(_p.text)[_k]) { _p.products = (_p.products || 0) + 1; break; }
