}

// Build the instruction that governs how many items a part must yield.
//   rows       = counted product rows in THIS part (0 when nothing tabular counted).
//   exact      = those rows came from a clean, separator-delimited table, so `rows`
//                is trustworthy as a hard target.
//   proseSource= this part ALSO carries running text that is part of the source (not
//                already-extracted context) and may itself list releases.
// When both a trustworthy table count AND prose are present, the count is asserted as
// a FLOOR for the table plus "extract every release in the text too" — never a hard
// total that could make the model drop a prose-only release. When the count is not
// trustworthy, no number is asserted at all (a wrong number is worse than none); the
// barcode audit in Build Raw Entry1 is the backstop.
function note(index, count, rows, exact, proseSource, bodyIsSource, atLeast, codes) {
  let core;
  if (rows > 0 && atLeast) {
    // v42: counted from what this part carries. A release that prints no barcode still has
    // to come back, so the number is a FLOOR and is stated as one — an exact total here
    // would invite the model to stop at N.
    // v48: the count is barcodes PLUS printed-but-empty barcode fields, so the sentence no
    // longer calls it a barcode count. It used to, and a model told "8 barcodes" that had
    // found 8 barcodes stopped there — with a ninth release, its UPC cell blank, still on
    // the page.
    core = 'This part contains AT LEAST ' + rows + ' releases — counted from the identifiers it prints PLUS the releases whose barcode or catalogue-number field is printed but left empty. Return one item for every release in it, reading top to bottom, and never fewer than ' + rows + '; a release whose barcode is blank, "TBC" or "N/A" comes back like any other, with ean null. Never sample, summarise, shorten or stop early; a release you skip is one the client never gets to sell.';
  } else if (rows > 0 && exact && !proseSource) {
    core = 'This part contains exactly ' + rows + ' product rows: return EXACTLY that many items, one per row, in the same order. Never sample, summarise, shorten or stop early — a row you skip is a release the client never gets to sell.';
  } else if (rows > 0 && exact && proseSource) {
    core = 'The table in this part has exactly ' + rows + ' product rows: return an item for EVERY one, one per row, none skipped. The message text above is ALSO part of this source — extract every release it lists in addition (there may be none). Never sample, summarise or stop early.';
  } else {
    core = 'Extract every single release this part contains — one item each, reading top to bottom. Never sample, summarise, shorten or stop early; a release you skip is one the client never gets to sell.';
  }
  // v58: NAME THE IDENTIFIERS, DO NOT ONLY COUNT THEM.
  // A count is an order the model can satisfy by miscounting; a list is an order per item,
  // and it is checkable — the model can see for itself which one it has not returned yet.
  // Part 4 of the I-DI invoice was told "AT LEAST 12", held 7 rows that read cleanly and a
  // page the parser had mangled, returned the 7 and stopped (client, 2026-09-10). Every
  // barcode named here is printed in THIS part — observed, never inferred — and each is
  // claimed by the FIRST part that carries it, so a barcode sitting in a repeated context
  // header is never ordered twice. The list is dropped above 40 identifiers, where a note
  // that long would itself be the thing the model skims.
  if (codes && codes.length && codes.length <= 40) {
    core += ' The identifiers printed in this part are: ' + codes.join(', ') +
      '. Return an item for every one of them — a line you find hard to read still comes back, carrying its barcode and whatever else that line does show — and an item for every release whose identifier field is printed empty as well.';
  }
  if (count === 1) return core;
  return 'PART ' + index + ' OF ' + count + ' of this source. ' + core +
    (bodyIsSource ? '' : ' The message text above is CONTEXT ONLY in this part — the items it lists were already extracted in an earlier part, so do not repeat them here.');
}

// ---- v64: AN EARLIER MESSAGE QUOTED INSIDE A FORWARD IS NOT THIS DOCUMENT ----------
//
// "Latest Message Only" cuts a reply at the attribution line above its quoted history, and
// deliberately cuts NOTHING when the mail is a forward, because the client forwards supplier
// mail in and there the forwarded block IS the payload. Correct — but a forward carries ONE
// message, and the history quoted inside THAT message is still history.
//
// Menart's invoice arrived that way (client, 2026-09-11): Marko forwarded Menart's reply,
// and inside it sat Nika's OWN order of 8 September, quoted back as a four-row table. The
// invoice supplies three of those four titles. The pipeline read the fourth barcode as
// "printed in this document but returned by no item", and the recovery pass dutifully
// manufactured a catalog row for AGRIKULTURA — a record Nika asked for and Menart did not
// send: no price, no invoice line, and on its way to the ERP as stock that does not exist.
//
// The text is NOT removed. Removing it could lose a release, and nothing here is worth that.
// It is DEMOTED: the model still reads every word, behind a marker saying what it is, while
// the three deterministic mechanisms that manufacture rows are scoped to the document's own
// content — the asserted release count, the identifier list the note ORDERS the model to
// return, and the barcode set the stub net and the recovery pass police. What is lost in the
// demoted region is redundancy, never data: the model still sees it and may still return a
// release from it.
//
// Two conditions, both required, and the second is what makes it safe:
//   1. the body is a FORWARD (otherwise the upstream cut already ran), and
//   2. an attachment prints at least one barcode — so the document of record is the
//      attachment. A mail with no barcoded attachment may have its releases nowhere but the
//      body, and is never demoted.
// The boundary regexes are byte-identical to the ones in "Latest Message Only"; the two
// nodes cannot share code, so they are kept in step by the tests.
const FWD_MARKER_RE = /^(?:[-_=]{2,}\s*)?(?:forwarded message|begin forwarded message|posredovano sporo[čc]ilo|weitergeleitete nachricht|message transf[ée]r[ée])/i;
const WROTE_RE = /(?:wrote|napisal(?:a|o)?|napisa[łl]a?|schrieb|a\s+[ée]crit|ha\s+scritto|escribi[óo]|skrev|schreef)\s*:$/i;
const ORIG_RE = /^[-_=]{2,}\s*(?:original message|urspr[üu]ngliche nachricht|message d'origine|izvirno sporo[čc]ilo)\s*[-_=]{2,}$/i;
const HDR_FROM_RE = /^(?:from|od|von|de|da|van|fra|nadawca)\s*:\s*\S/i;
const HDR_NEXT_RE = /^(?:sent|date|poslano|datum|gesendet|envoy[ée]|inviato|enviado|verzonden|to|za|an|cc|subject|zadeva|betreff|objet|oggetto|asunto|onderwerp)\s*:/i;
const QUOTED_MARK = '[AN EARLIER MESSAGE, QUOTED INSIDE THIS FORWARD — CONTEXT ONLY. Everything below this line was sent BEFORE the message above and is quoted back inside it. On this mail the document of record is the attachment. Read these lines to understand the conversation, but do not return a release from them: what somebody ASKED FOR is not what was supplied, and everything actually supplied is printed in the attachment above.]';

function deMarkLine(line) {
  return String(line == null ? '' : line)
    .replace(/^[>\s]+/, '')
    .replace(/[*_`]/g, '')
    .replace(/\\/g, '')
    .trim();
}

// { own, quoted } — `quoted` is '' when nothing is demoted.
function splitQuotedHistory(body, att) {
  const s = String(body == null ? '' : body).replace(/\r\n/g, '\n');
  const none = { own: s, quoted: '' };
  if (!s.trim()) return none;
  if (!BARCODE_RE.test(String(att == null ? '' : att))) return none;   // no barcoded attachment -> the body may be all there is
  const lines = s.split('\n');
  let fwd = -1;
  for (let i = 0; i < lines.length; i++) { if (FWD_MARKER_RE.test(deMarkLine(lines[i]))) { fwd = i; break; } }
  if (fwd < 0) return none;                                           // not a forward: the upstream cut already ran
  // The forwarded message's OWN header block belongs to it, not to the history below it.
  let i = fwd + 1;
  while (i < lines.length) {
    const l = deMarkLine(lines[i]);
    if (l === '' || HDR_FROM_RE.test(l) || HDR_NEXT_RE.test(l)) { i++; continue; }
    break;
  }
  for (let k = i; k < lines.length; k++) {
    const l = deMarkLine(lines[k]);
    if (!l) continue;
    let hit = ORIG_RE.test(l) || (l.length <= 400 && WROTE_RE.test(l));
    if (!hit && HDR_FROM_RE.test(l)) {
      for (let m = k + 1; m <= k + 4 && m < lines.length; m++) {
        if (HDR_NEXT_RE.test(deMarkLine(lines[m]))) { hit = true; break; }
      }
    }
    if (!hit) continue;
    return { own: lines.slice(0, k).join('\n').replace(/\s+$/, ''), quoted: lines.slice(k).join('\n') };
  }
  return none;
}

function chunkSource(inputs) {
  const out = [];
  for (let i = 0; i < inputs.length; i++) {
    const src = inputs[i].json;
    const att = src.attachments_text || '';
    // v64: an earlier message quoted inside this forward is read but never counted, never
    // ordered and never policed. See splitQuotedHistory above.
    const _hist = splitQuotedHistory(src.body || '', att);
    const body = _hist.own;
    const quoted = _hist.quoted;
    let quotedShown = false;
    const withQuoted = function (text) {
      if (!quoted || quotedShown) return text;
      quotedShown = true;
      return String(text == null ? '' : text) + '\n\n' + QUOTED_MARK + '\n' + quoted;
    };
    const B = chunkBlob(body, false);
    const A = chunkBlob(att, true);
    const total = B.total + A.total;          // product rows -> the count the model is given
    const rowTotal = B.rowTotal + A.rowTotal;  // all rows -> the size the splitter works on

    // body_full stays the record of what ARRIVED; body_own is the part of it that is this
    // document's own content, which is what the completeness gate and the recovery pass police.
    const base = Object.assign({}, src, { body_full: src.body || '', attachments_full: att, body_own: body, body_quoted: quoted });
    // v58: the text as chunkBlob left it — an unaligned table rewritten one line per release.
    // Two emit paths took their text straight from `src` instead, so a rewrite reached the
    // model only when the document happened to be long enough to be SPLIT — the opposite of
    // what a one-page mangled invoice needs. With nothing to rewrite these are byte-identical
    // to the originals, so no other document changes. `*_full` stays raw on purpose: it is
    // the record of what arrived.
    const attFlat = (A.parts && A.parts[0]) ? A.parts[0].text : att;
    const bodyFlat = (B.parts && B.parts[0]) ? B.parts[0].text : body;

    // Whole source fits in one AI call. Assert an exact count only when the tables are
    // clean AND there is no substantial prose that might carry its own releases.
    if (rowTotal <= MAX_ROWS) {
      const cleanTables = (A.total === 0 || A.confident) && (B.total === 0 || B.confident);
      const proseSource = (A.prose + B.prose) > 40; // running text beyond the table(s)
      let exact = total > 0 && cleanTables;
      const codes1 = barcodeList(bodyFlat + '\n' + attFlat);
      // The floor may never sit below the number of identifiers we can name. If it does,
      // the count was wrong, and a wrong count asserted as EXACTLY is an order to drop rows.
      let rows1 = total;
      if (codes1.length > rows1) { rows1 = codes1.length; exact = false; }
      out.push({
        json: Object.assign({}, base, {
