for (let i = 0; i < ai.length; i++) {
  let s = null;
  // 1. what n8n says, while it can still say it.
  try { s = $('Chunk Source').itemMatching(i).json; } catch (e) { s = null; }
  // 2. one AI call per part, in order: when the counts agree, item i IS part i. This is what
  //    saves the run if the pairing is ever lost upstream too.
  if (!s && allChunks.length === ai.length) s = allChunks[i];
  // 3. only then the old fallback, which attributes everything to the first part.
  if (!s) { try { s = $('Chunk Source').first().json; } catch (e2) { s = {}; } }
  chunks.push(s);
  srcKeys.push(chunkKey(s));
  const id = s.message_id == null ? 'unknown' : s.message_id;
  if (!printed[id]) {
    // v64: body_own excludes an earlier message quoted inside a forward - what somebody asked
    // for in a previous mail is not a barcode this document dropped. Falls back to the full
    // body when Chunk Source did not set it.
    printed[id] = printedIn(
      String(s.attachments_full == null ? (s.attachments_text || '') : s.attachments_full) + '\n' +
      String(s.body_own == null ? (s.body_full == null ? (s.body || '') : s.body_full) : s.body_own));
    returned[id] = {};
    firstIdx[id] = i;
    order.push(id);
  }
  const r = parseOut(ai[i]);
  const items = (r && r.items) || [];
  for (const it of items) { const k = keyEan(it && it.ean); if (k) returned[id][k] = true; }
}

// The fullest rendering of a barcode's own line, and which chunk it came from. The text the
// model was actually shown wins over the raw parse: where an unaligned table was rewritten one
// line per release (v58/v59) the raw parse holds only the fragment the parser broke the record
// into, and a fragment is exactly what the first pass already failed to read.
function lineFor(id, raw) {
  let best = '', at = -1;
  for (let i = 0; i < chunks.length; i++) {
    const s = chunks[i];
    if ((s.message_id == null ? 'unknown' : s.message_id) !== id) continue;
    for (const src of [String(s.attachments_text || ''), String(s.body || ''),
                       String(s.attachments_full || ''), String(s.body_full || '')]) {
      for (const l of src.split('\n')) {
        if (l.indexOf(raw) === -1) continue;
        if (l.length > best.length) { best = l; at = i; }
        break;
      }
    }
  }
  return { line: best.trim().slice(0, 400), at: at };
}

const targets = [];
for (const id of order) {
  const p = printed[id] || {}, got = returned[id] || {};
  for (const k in p) {
    if (!Object.prototype.hasOwnProperty.call(p, k)) continue;
    if (got[k]) continue;
    if (targets.length >= MAX_RECOVER) break;
    const hit = lineFor(id, p[k]);
    // No line to read means nothing to ask about, and a question with no source invites the
    // model to answer from what it knows about the release. The stub stays a stub instead.
    if (!hit.line) continue;
    targets.push({ source: id, ean: p[k], key: k, line: hit.line, at: hit.at >= 0 ? hit.at : firstIdx[id] });
  }
}

return [{
  json: {
    needs_recovery: targets.length > 0,
    count: targets.length,
    targets: targets,
    lines: targets.map(function (t, i) { return (i + 1) + '. ' + t.line; }).join('\n'),
    ai: ai,
    srcKeys: srcKeys,   // v61: one per AI item, in order — the pairing, carried by hand
  },
}];

parameters.text:
={{ $json.count }} product line(s) copied verbatim from a supplier document. The first pass returned no item for any of them.

Return one item for each line, in this order, each carrying the barcode exactly as printed at the start of its line.

{{ $json.lines }}

parameters.jsCode:
// v60: THE RECOVERY PASS, STEP 2 — PUT WHAT THE SECOND PASS READ BACK INTO THE FIRST PASS'S
// OWN OUTPUT, so it flows through EXACTLY the same pipeline as every other item.
//
// A recovered release is APPENDED to the items of the chunk whose text prints its barcode. The
// item count and the chunk pairing that Build Catalog Rows depends on are therefore unchanged,
// and the recovered release then gets the same field transforms, the same label resolution,
// the same exclusion rules and the same matching against open and sent lines as a release the
// first pass returned. Nothing downstream is duplicated or special-cased, and the completeness
// gate counts it as produced — so no stub is created for it, because it is no longer missing.
//
// Four rules the recovery may never break:
//   1. it may only ANSWER, never ADD. An ean that was not asked about is discarded; the second
//      pass is not allowed to introduce a release, only to read one we already know is there.
//   2. the barcode is OURS, not the model's. It is copied from the document, so a mis-typed
//      digit cannot become a catalog line that looks right and is wrong. A wrong barcode is
//      worse than a missing one: a missing one is caught, a wrong one sends cleanly.
//   3. an answer with neither artist nor title is discarded. An empty row is worse than the
//      stub it would replace, because a stub says WHY it is empty.
//   4. every recovered row is flagged for review. It was read from the part of the page the
//      parser mangled; it is data, not a guess, but a human confirms it before it is approved.
// And if anything at all goes wrong in here, the first pass's output is returned untouched:
// the recovery is an improvement on the stub net, never a risk to it.
const req = ($('Find Dropped Barcodes').first() || { json: {} }).json || {};
const ai = req.ai || [];
// v61: every item this node emits carries the key of the chunk it came from, on BOTH paths —
// the untouched passthrough and the merged output. Build Catalog Rows reads that instead of
// asking n8n, which can no longer answer once this node has expanded one item back into N.
const srcKeys = req.srcKeys || [];
function stamp(j, i) { const o = Object.assign({}, j); if (srcKeys[i]) o._chunk_key = srcKeys[i]; return { json: o }; }
const passthrough = ai.map(stamp);

function parseOut(r) {
  let o = r.output ?? (r.message && r.message.content) ?? r.content ?? r;
  if (typeof o === 'string') {
    const a = o.indexOf('{'), b = o.lastIndexOf('}');
    try { o = JSON.parse(a >= 0 && b > a ? o.slice(a, b + 1) : o); } catch (e) { o = null; }
  }
  return o;
}
function keyEan(v) { const d = String(v == null ? '' : v).replace(/\D/g, '').replace(/^0+/, ''); return d || null; }
function blank(v) { return v == null || String(v).trim() === ''; }

let out = passthrough;
try {
  const targets = req.targets || [];
  if (!req.needs_recovery || !targets.length || !ai.length) return passthrough;

  // On the branch where no recovery was needed this node is fed the request itself, and if the
  // AI call failed it is fed whatever the node passed through. Either way: no items, no merge.
  let answer = null;
  for (const r of $input.all().map(function (i) { return i.json; })) {
    const o = parseOut(r);
    if (o && Array.isArray(o.items) && o.items.length) { answer = o; break; }
  }
  if (!answer) return passthrough;

  const wanted = {};
  for (const t of targets) wanted[t.key] = t;

  // work on copies: a chunk we do not touch is passed through byte for byte
  const parsed = ai.map(function (j) { return null; });
  const used = {};
  let merged = 0;

  for (const a of answer.items) {
    if (!a || typeof a !== 'object') continue;
    const k = keyEan(a.ean);
    if (!k || !wanted[k] || used[k]) continue;              // rule 1: only ever an answer
    if (blank(a.artist) && blank(a.title)) continue;         // rule 3: an empty row helps nobody
    const t = wanted[k];

    // find a chunk of this release's own source whose output we can actually append to
    let at = -1;
    for (const cand of [t.at]) {
      if (cand == null || cand < 0 || cand >= ai.length) continue;
      if (parsed[cand] === null) parsed[cand] = parseOut(ai[cand]);
      if (parsed[cand] && Array.isArray(parsed[cand].items)) { at = cand; break; }
    }
    if (at === -1) {
      for (let i = 0; i < ai.length; i++) {
        if (parsed[i] === null) parsed[i] = parseOut(ai[i]);
        if (parsed[i] && Array.isArray(parsed[i].items)) { at = i; break; }
      }
    }
    if (at === -1) continue;    // nothing parseable to append to: the stub still catches it

    used[k] = true;
    merged++;
    parsed[at].items.push({
      artist_raw: a.artist_raw ?? a.artist ?? null,
      artist: a.artist ?? null,
      artist_kind: a.artist_kind ?? null,
      artist_family_name: a.artist_family_name ?? null,
      artist_given_name: a.artist_given_name ?? null,
      artist_people: a.artist_people ?? null,
      title: a.title ?? null,
      features: Array.isArray(a.features) ? a.features : [],
      label: a.label ?? null,
      format: a.format ?? null,
      genre: a.genre ?? null,
      unit: a.unit ?? 1,
      ean: t.ean,                       // rule 2: the document's barcode, not the model's
      catalogue_no: a.catalogue_no ?? null,
      release_date: a.release_date ?? null,
      price: a.price ?? null,
      currency: a.currency ?? null,
      cop: a.cop ?? null,
      ppd_eur: a.ppd_eur ?? null,
      rock_bottom: a.rock_bottom ?? null,
      calculation_group: a.calculation_group ?? '1',
      // The second pass reads ONE line at a time and is given no exclusion rules, so it is in
      // no position to judge one. Exclusion stays where it already works, on the text.
      excluded: false,
      exclusion_reason: null,
      missing_mandatory: [],
      item_confidence: 0.5,
      item_notes: null,
      recovered: true,                  // rule 4: Build Catalog Rows flags it for review
      recovered_from: t.line,
    });
  }

  if (!merged) return passthrough;
  out = ai.map(function (j, i) {
    return stamp((parsed[i] && Array.isArray(parsed[i].items)) ? { output: JSON.stringify(parsed[i]) } : j, i);
  });
} catch (e) {
  return passthrough;
}
return out;

// v63: WHAT THE DATABASE REFUSED MUST BE SAID OUT LOUD.
//
// `Insert Catalog Line` is deliberately set to onError = continueRegularOutput, because the
// partial unique index `catalog_lines_code_uniq` on `code` is how a repeat barcode is dropped:
// the matcher loads `catalog <> 'processed'`, so a barcode that exists only in the frozen
// already-sent set looks new, the workflow decides `create`, and Postgres refuses the insert.
// That rule is the client's own ("a repeat EAN already sent to Hermes is disregarded"); the
// SILENCE around it was the problem — the row simply was not there and nothing said why
// (client, 2026-09-11: "where can i see which items were not inserted because of duplication?").
//
// This node sits on the loop's done branch, which was a dead end, and reads back every insert
// result the loop accumulated. It writes nothing and it cannot affect the run: it is the last
// node on its branch, and if it throws, everything has already been written.
const results = $input.all().map(function (i) { return i.json || {}; });

function errText(j) {
  const e = j.error !== undefined && j.error !== null ? j.error
    : (j.errorMessage !== undefined && j.errorMessage !== null ? j.errorMessage : null);
  if (e === null || e === undefined) return null;
  if (typeof e === 'string') return e;
  const s = e.message || e.description || e.detail || e.hint || '';
  return s ? String(s) : JSON.stringify(e).slice(0, 400);
}
const DUPE_RE = /duplicate key|already exists|unique constraint|catalog_lines_code_uniq|\b23505\b/i;

const refused = [];
for (const j of results) {
  const t = errText(j);
  if (!t) continue;
  const dupe = DUPE_RE.test(t);
  refused.push({
    ean: j.ean !== undefined ? j.ean : null,
    code: j.code !== undefined ? j.code : null,
    artist: j.artist !== undefined ? j.artist : null,
    title: j.title !== undefined ? j.title : null,
    label: j.label !== undefined ? j.label : null,
    was_it_a_duplicate: dupe,
    what_happened: dupe
      ? 'DROPPED AS A DUPLICATE. A catalog line with this barcode already exists, so the database refused the new line (catalog_lines_code_uniq) and it was NOT inserted. Most often the existing line sits in the "processed" catalog — already sent to Hermes — which the matcher does not load, which is why this run read the release as new. Nothing is lost: the release is already in the catalog. Run supabase/find-skipped-duplicates.sql to see it.'
      : 'NOT INSERTED, and NOT because of a duplicate. Read `error` below — this one needs looking at.',
    error: String(t).slice(0, 400),
  });
}

const attempted = (function () {
  try {
    return $('Build Catalog Rows').all().filter(function (x) {
      return x.json && x.json.action === 'create';
    }).length;
  } catch (e) { return null; }
})();
const dupes = refused.filter(function (r) { return r.was_it_a_duplicate; }).length;
const other = refused.length - dupes;

return [{ json: {
  new_lines_attempted: attempted,
  new_lines_inserted: attempted === null ? null : Math.max(0, attempted - refused.length),
  dropped_as_duplicates: dupes,
  failed_for_another_reason: other,
  summary: refused.length === 0
    ? 'Every new line was inserted. Nothing was dropped as a duplicate.'
    : (dupes ? dupes + ' new line(s) were DROPPED AS DUPLICATES — the barcode already has a catalog line (most likely already sent to Hermes). ' : '') +
      (other ? other + ' new line(s) failed for another reason — read `error`. ' : '') +
      'They are listed below, with the barcode as the workflow tried to write it.',
  dropped: refused,
} }];

// v63: A PART THE AI ANSWERED UNREADABLY MUST NOT LOOK LIKE A PART IT JUDGED IRRELEVANT.
//
// The `If` before this node asks one question — is_catalog_relevant — and its expression ends
// `catch(e){ return false; }`. So an answer that cannot be parsed as JSON takes the SAME branch
// as a part the model deliberately judged irrelevant, and that branch went nowhere.
//
// On the 11.09 PIAS list the model answered part 1 of 5 with seven of its thirty-one releases
// followed by a JavaScript comment ("// Additional items follow the same structure, up to the
// required 31 items") — not JSON. The whole part vanished here, taking with it the assertion
// that told the completeness gate to expect 31 releases. The run survived only because the other
// four parts still carry the full document text, so every printed barcode was found anyway and
// the recovery pass read back all eighteen missing releases. A release in that part printing NO
// barcode would have been lost in total silence (client, 2026-09-11).
//
// This node writes nothing and changes nothing. It says which of the two happened.
function parsed(j) {
  let v = j.output;
  if (v === undefined || v === null) v = (j.message && j.message.content !== undefined) ? j.message.content : (j.content !== undefined ? j.content : j);
  if (typeof v === 'string') {
    const a = v.indexOf('{'), b = v.lastIndexOf('}');
    try { return JSON.parse(a >= 0 && b > a ? v.slice(a, b + 1) : v); } catch (e) { return null; }
  }
  return v && typeof v === 'object' ? v : null;
}
function rawText(j) {
  const v = j.output;
  if (typeof v === 'string') return v;
  try { return JSON.stringify(v === undefined ? j : v); } catch (e) { return String(v); }
}

const chunks = (function () {
  try { return $('Chunk Source').all().map(function (i) { return i.json; }); } catch (e) { return []; }
})();

const parts = $input.all().map(function (i, n) {
  const j = i.json || {};
  const p = parsed(j);
  const raw = rawText(j);
  if (p === null) {
    return {
      verdict: 'UNREADABLE ANSWER — this is a fault, not a decision.',
      what_it_means: 'The model\'s answer for this part of the document is not valid JSON, so NOTHING was extracted from it on the first pass. The recovery pass still reads back every release whose barcode is printed in the document, and the completeness note on the catalog rows accounts for those. A release in this part that prints NO barcode at all is lost — check the source for one, and re-run the email.',
      answer_length: String(raw).length,
      answer_starts: String(raw).slice(0, 240),
      answer_ends: String(raw).slice(-240),
    };
  }
  return {
    verdict: 'NOT CATALOG RELEVANT — the model judged this part not to belong in the catalog.',
    what_it_means: 'Normal for a signature, a covering note or an image. WRONG if this part of the document held releases — read the reason and the item count below, then check the source.',
    document_type: p.document_type !== undefined ? p.document_type : null,
    relevance_reason: p.relevance_reason !== undefined ? p.relevance_reason : null,
    items_the_model_returned: Array.isArray(p.items) ? p.items.length : 0,
    label_it_read: p.label !== undefined ? p.label : null,
  };
});

const unreadable = parts.filter(function (p) { return /^UNREADABLE/.test(p.verdict); }).length;
return [{ json: {
  parts_the_document_was_split_into: chunks.length || null,
  parts_that_produced_nothing: parts.length,
  of_those_unreadable: unreadable,
  summary: unreadable
    ? unreadable + ' part(s) of this document came back from the AI as something that could not be read. Everything in them was skipped on the first pass — see what_it_means.'
    : parts.length + ' part(s) were judged not catalog relevant. Check that none of them held releases.',
  parts: parts,
} }];
